CREATE DATABASE IF NOT EXISTS pinkflow_projectmandiri CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE pinkflow_projectmandiri;
CREATE TABLE IF NOT EXISTS admins(id INT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(60) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS products(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,category VARCHAR(100) NOT NULL,price DECIMAL(12,2) NOT NULL DEFAULT 0,stock INT NOT NULL DEFAULT 0,image VARCHAR(255) DEFAULT '',description TEXT,is_active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS orders(id INT AUTO_INCREMENT PRIMARY KEY,order_code VARCHAR(40) UNIQUE,order_type ENUM('catalog','custom') NOT NULL DEFAULT 'catalog',customer_name VARCHAR(160) NOT NULL,phone VARCHAR(40) NOT NULL,address TEXT,total DECIMAL(12,2) NOT NULL DEFAULT 0,status VARCHAR(60) NOT NULL DEFAULT 'Menunggu Konfirmasi',pickup_date DATE NULL,pickup_time TIME NULL,custom_details TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS order_items(id INT AUTO_INCREMENT PRIMARY KEY,order_id INT NOT NULL,product_id INT NULL,product_name VARCHAR(160) NOT NULL,price DECIMAL(12,2) NOT NULL,quantity INT NOT NULL,subtotal DECIMAL(12,2) NOT NULL,CONSTRAINT fk_order_items_order FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE) ENGINE=InnoDB;
